+  }
+  if (!isObject(candidate.provenance)) {
+    failures.push('response_candidate_provenance_required');
+  }
+  return [...new Set(failures)].sort(compareByteOrder);
+}
+
+export function validateSemanticKgExternalModelResponse({ packet, response } = {}) {
+  const failureCodes = [];
+  if (!isObject(packet)) {
+    failureCodes.push('packet_required');
+  }
+  if (!isObject(response)) {
+    return {
+      valid: false,
+      candidate_count: 0,
+      accepted_edge_count: 0,
+      failure_codes: ['response_record_required'],
+      candidate_results: [],
+    };
+  }
+
+  for (const field of buildExternalModelResponseSchema().required_top_level_fields) {
+    if (!Object.hasOwn(response, field)) {
+      failureCodes.push(`response_${field}_required`);
+    }
+  }
+  if (response.schema_version !== 'semantic_kg_candidate_generation_response.v1') {
+    failureCodes.push('response_schema_version_invalid');
+  }
+  if (isObject(packet) && response.packet_id !== packet.packet_id) {
+    failureCodes.push('response_packet_id_mismatch');
+  }
+  if (!Array.isArray(response.candidates)) {
+    failureCodes.push('response_candidates_array_required');
+  }
+
+  const candidateResults = Array.isArray(response.candidates)
+    ? response.candidates.map((candidate) => ({
+      candidate_id: candidate?.candidate_id ?? null,
+      valid: validateResponseCandidate({ packet, candidate }).length === 0,
+      failure_codes: validateResponseCandidate({ packet, candidate }),
+    }))
+    : [];
+
+  const candidateFailureCodes = candidateResults.flatMap((result) => result.failure_codes);
+  const acceptedEdgeCount = Array.isArray(response.candidates)
+    ? response.candidates.filter((candidate) => candidate?.status === 'accepted').length
+    : 0;
+  const allFailureCodes = [...new Set([...failureCodes, ...candidateFailureCodes])]
+    .sort(compareByteOrder);
+
+  return {
+    valid: allFailureCodes.length === 0 && acceptedEdgeCount === 0,
+    candidate_count: Array.isArray(response.candidates) ? response.candidates.length : 0,
+    accepted_edge_count: acceptedEdgeCount,
+    failure_codes: allFailureCodes,
+    candidate_results: candidateResults,
+  };
+}
+
+function buildReadback({ harness, packets, receipt, outputs, validatorResult }) {
+  const failedChecks = validatorResult.checks
+    .filter((check) => check.status !== 'pass')
+    .map((check) => check.id);
+  return [
+    '# Semantic KG Candidate Generator Harness Readback',
+    '',
+    `Generated at: ${harness.generated_at}`,
+    `Issue: #${ISSUE}`,
+    `Parent: #${PARENT_ISSUE}`,
+    '',
+    '## Boundary',
+    '',
+    '- Mode: no-auth dry-run',
+    '- External model status: external_model_not_run',
+    `- Blocked before network client setup: ${receipt.blocked_before_network_client_setup}`,
+    `- External model calls: ${receipt.external_model_call_count}`,
+    `- Accepted edges emitted: ${outputs.summary.accepted_edge_count}`,
+    '',
+    '## Artifacts',
+    '',
+    `- Harness: \`${harness.output_artifacts.harness}\``,
+    `- Packet examples: \`${harness.output_artifacts.packets}\``,
+    `- No-auth receipt: \`${harness.output_artifacts.receipt}\``,
+    `- Raw candidates: \`${harness.output_artifacts.raw_candidates}\``,
+    `- Validator: \`${harness.output_artifacts.validator}\``,
+    '',
+    '## Counts',
+    '',
+    `- Packet examples: ${packets.summary.packet_count}`,
+    `- Raw local heuristic candidates: ${outputs.summary.raw_candidate_count}`,
+    `- Local heuristic candidates explicitly marked: ${outputs.summary.local_heuristic_candidate_count}`,
+    `- Runtime-consumable candidates: ${outputs.summary.runtime_consumption_allowed_count}`,
+    '',
+    '## Validation',
+    '',
+    `- Status: ${validatorResult.summary.validation_status}`,
+    `- Failed checks: ${failedChecks.length === 0 ? 'none' : failedChecks.join(', ')}`,
+    '',
+    '## Notes',
+    '',
+    'This harness only prepares minimal context packets and local raw candidate shells. It does not call an external model, set up a network/model client, promote candidates, mutate Supabase, touch frontend surfaces, or reindex RAG.',
+    '',
+  ].join('\n');
+}
+
+export function buildSemanticKgCandidateGeneratorHarness(options = {}) {
+  const root = rootFromOptions(options);
+  const paths = {
+    ...DEFAULT_PATHS,
+    ...(options.paths ?? {}),
+  };
+  const generatedAt = options.generatedAt ?? DEFAULT_GENERATED_AT;
